import{H as e,Q as t,bt as n,gt as r,it as i,nt as a,rt as o,tt as s}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var c=JSON.parse(`{"title":"Comments and Review","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/comments-and-review.md","filePath":"reporting/comments-and-review.md","lastUpdated":1781102819000}`),l={name:`reporting/comments-and-review.md`};function u(e,c,l,u,d,f){let p=n(`BadgePro`);return r(),s(`div`,null,[c[0]||=t(`div`,{style:{display:`none`},hidden:`true`,"aria-hidden":`true`,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /reporting/comments-and-review.md for this page in Markdown format`,-1),c[1]||=t(`h1`,{id:`comments-and-review`,tabindex:`-1`},[o(`Comments and Review `),t(`a`,{class:`header-anchor`,href:`#comments-and-review`,"aria-label":`Permalink to “Comments and Review”`},`​`)],-1),i(p),c[2]||=a(`<p>Before a report goes to the client, findings and sections usually pass through an internal review. <strong>Statuses</strong> and <strong>assignees</strong> show where each item stands and who owns it. On SysReptor Professional, <strong>comments</strong> let the team discuss specific report fields without leaving the editor.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to “Comments”">​</a></h2><p>Comments are available on report sections and findings. You can attach them to <strong>any report field</strong> (markdown, string, CVSS, and so on) or to a <strong>text selection</strong> inside a markdown field. Selection comments are highlighted in the editor and quoted in the sidebar.</p><p><img src="/images/comments.png" alt="Comments on report fields" width="1006" height="407"></p><p>The <strong>Comments</strong> sidebar groups threads by field. Each comment supports <strong>replies</strong>.</p><p><code>@username</code> mentions notify project members; assignees are notified when someone comments on their finding or section. See <a href="/users/notifications">Notifications</a>.</p><p>Comments sync in real time with <a href="/reporting/collaborative-editing">collaborative editing</a> on the same item.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to “Statuses”">​</a></h2><p>Every finding and report section has a <strong>status</strong> and an optional <strong>assignee</strong> (a project member).</p><p>Out of the box you get <em>In progress</em>, <em>Ready for review</em>, <em>Needs improvement</em>, and <em>Finished</em>. Your instance may show more if an admin added custom statuses.</p><p>Set status and assignee in the toolbar when you open a finding or section. The report sidebar shows both for every section and finding, so you can scan progress without opening each item. If your design defines a retest status field, that appears in the sidebar as well.</p><p>Marking one finding <em>Finished</em> is not the same as finishing the project. When you mark a <strong>project as finished</strong> in project settings, the whole project becomes read-only until someone reactivates it.</p><h2 id="custom-status-workflows" tabindex="-1">Custom status workflows <a class="header-anchor" href="#custom-status-workflows" aria-label="Permalink to “Custom status workflows”">​</a></h2><p>By default you can move between any status. Some teams want a fixed review flow — for example, <em>In progress</em> may only go to <em>Ready for review</em>, and only from there to <em>Finished</em> or <em>Needs improvement</em>.</p><p>Instance administrators configure that with <code>STATUS_DEFINITIONS</code> and <code>allowed_next_statuses</code>. Examples and the full option list are in <a href="/setup/configuration#custom-statuses">Custom Statuses</a>. Superusers with admin permissions can override restricted transitions when they need to correct a status.</p>`,15)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};